local KTool = CS.Engine.Lib.KTool
------------ import ------------

------------ define ------------

------------ define ------------
local RewardACount = 3  ---奖励数量上限为3

--- from: Assets/BundleResources/Prefabs/RegressionNew/RegressionNewDailyPanel5010.prefab > name: RewardNode
---@class RegressionNewDailyCellNode
---@field Env                           	RegressionNewDailyCellNode              
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field ImgSelectGroup                	UnityEngine.RectTransform               	@ 0    
---@field ImgReceivedMark               	UnityEngine.RectTransform               	@ 1    
---@field StateNotAvailable             	UnityEngine.RectTransform               	@ 2    
---@field GoodNode1                     	UnityEngine.RectTransform               	@ 3    
---@field GoodNode2                     	UnityEngine.RectTransform               	@ 4    
---@field TextDay                       	TMPro.TextMeshProUGUI                   	@ 5    
---@field ImgBg                         	UnityEngine.RectTransform               	@ 6    
---@field BtnCardSigninNode             	UnityEngine.RectTransform               	@ 7    
local RegressionNewDailyCellNode = Class("RegressionNewDailyCellNode")
function RegressionNewDailyCellNode:__init()
	self.btnAction = nil
	self.index = nil
end

function RegressionNewDailyCellNode:__delete()
	self.btnAction = nil
	self.index = nil
	self.controller = nil
end

---SetCallBack
---设置单击回调函数
function RegressionNewDailyCellNode:SetBtnCallBack(cb)
	self.btnAction = cb
end

function RegressionNewDailyCellNode:Awake()
	SetButtonAction(self.BtnCardSigninNode, function ()
		if type(self.btnAction) == 'function' then
			local isCanDraw = self:IsCanDraw()
			if isCanDraw then
				self.btnAction(self.data.day, self.index)
			else
				local isHasDraw = self:IsHaveDraw()
				if isHasDraw then
					GameUtils.Toast(localize("奖励已领取"))
				else
					GameUtils.Toast(localize("还未满足领取条件"))
				end
			end
		end
	end)
end

function RegressionNewDailyCellNode:FreshBaseUI(data, index)
	self.data = checkTable(data)
	self.index = index
	CfUtils.FillText(self.TextDay,checkNumber(self.data.day) < 10 and string.format("0%s",self.data.day) or self.data.day)
	self:RefreshRewards()
	self:RefreshStatus()
end

function RegressionNewDailyCellNode:RefreshRewards()
	for i = 1, RewardACount do
		local GoodNode = self["GoodNode"..i]
		if isNotNull(GoodNode) then
			local rewards = self.data.rewards
			if rewards[i] then
				---@type GoodNodeMB
				local goodNodeMbEnv = CfUtils.GetLuaScr(GoodNode,Constants.UILuaTablePath.GoodNodeMB)
				local reward = rewards[i]
				goodNodeMbEnv:Reload({
					goodsId = reward.goodsId,
					text = string.format("x%d", reward.num),
					isShowNo = true
				})
				
				goodNodeMbEnv:SetClickButtonAction(function()
					if self:IsCanDraw() then
						self.btnAction(self.data.day, self.index)
					else
						local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(reward.goodsId)
						if isTable(vo) then
							GameUtils.ShowCommonTipsBoard(GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
						end
					end
				end)
				
				CfUtils.SetActive(GoodNode.gameObject,true)
			else
				CfUtils.SetActive(GoodNode.gameObject,false)
			end
		end
	end
end

function RegressionNewDailyCellNode:SetStates(status)
	self.data.status = status
end

---是否显示当前天数的选中外框
function RegressionNewDailyCellNode:SetSelectedGroupShow(isShow)
	KTool.SetActive(self.ImgSelectGroup, isShow)
	if isShow then
		self:PlayOpenAnim()
	end
end

function RegressionNewDailyCellNode:RefreshStatus()
	local isReceived = self:IsHaveDraw()
	KTool.SetActive(self.ImgReceivedMark, isReceived)
	
	if not isReceived then
		local isCanDraw = self:IsCanDraw()
		self:SetSelectedGroupShow(isCanDraw)
	end
end

function RegressionNewDailyCellNode:IsCanDraw()
	return self.data.status == Constants.GetStatus.Can
end

function RegressionNewDailyCellNode:IsHaveDraw()
	return self.data.status == Constants.GetStatus.Has
end

function RegressionNewDailyCellNode:PlayOpenAnim()
	CfUtils.PlayAnimator(self.ImgSelectGroup, "Go")
end

function RegressionNewDailyCellNode:OnDestroy()
	self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
	self:Delete()
	self = nil --lua层的gc需要
end

return RegressionNewDailyCellNode